timestamp_contract_references.source:
return `# ${outline.title || 'Thesis draft'}

Private draft compiled from saved canonical Notes. Chapter statuses are user-reported; word counts use whitespace. This export does not verify citations or academic acceptance.

` + outline.chapters.map(row => `## ${row.title}

Status: ${row.status}; target: ${row.target_words} words

${row.guidance ? `Chapter guidance: ${row.guidance}

` : '
